inputs = ['bfii', 'fzyzdk', 'ki', 'hjx', 'azfbu']
outputs = ['ivbhwuu', 'bhwzyzdk', 'ku', 'hjx', 'azbhwivu']

# Let me manually trace through what each transformation looks like
print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{out}'")
    if inp != out:
        # Find what changed
        if len(inp) <= len(out):
            # Look for insertion patterns
            diff_start = 0
            while diff_start < len(inp) and inp[diff_start] == out[diff_start]:
                diff_start += 1

            diff_end = len(inp)
            while diff_end > diff_start and inp[diff_end-1] == out[diff_end-1]:
                diff_end -= 1

            if diff_start < diff_end:
                removed = inp[diff_start:diff_end]
                inserted = out[diff_start:diff_start+len(removed)]
                print(f"  Removed '{removed}', Inserted '{inserted}' at position {diff_start}")
            else:
                # Might be a replacement
                for j in range(len(inp)):
                    if inp[j] != out[j]:
                        print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        else:
            # Removal case
            print(f"  Looks like removal occurred")

